// static
bool BraveBrowserCommandHandlerStubDispatch::AcceptWithResponder(
    BraveBrowserCommandHandler* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::internal::ResponderThunk> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (static_cast<messages::BraveBrowserCommandHandler>(message->header()->name)) {
    case messages::BraveBrowserCommandHandler::kCanExecuteCommand: {
      internal::BraveBrowserCommandHandler_CanExecuteCommand_Params_Data* params =
          reinterpret_cast<
              internal::BraveBrowserCommandHandler_CanExecuteCommand_Params_Data*>(
                  message->mutable_payload());
      

      // Validation for BraveBrowserCommandHandler.0
      bool success = true;
      Command p_command_id{};
      BraveBrowserCommandHandler_CanExecuteCommand_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadCommandId(&p_command_id))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            BraveBrowserCommandHandler::Name_, 0, false);
        return false;
      }
      auto callback =
          BraveBrowserCommandHandler_CanExecuteCommand_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->CanExecuteCommand(        
        std::move(p_command_id), std::move(callback));
      return true;
    }
    case messages::BraveBrowserCommandHandler::kExecuteCommand: {
      internal::BraveBrowserCommandHandler_ExecuteCommand_Params_Data* params =
          reinterpret_cast<
              internal::BraveBrowserCommandHandler_ExecuteCommand_Params_Data*>(
                  message->mutable_payload());
      

      // Validation for BraveBrowserCommandHandler.1
      bool success = true;
      Command p_command{};
      BraveBrowserCommandHandler_ExecuteCommand_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadCommand(&p_command))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            BraveBrowserCommandHandler::Name_, 1, false);
        return false;
      }
      auto callback =
          BraveBrowserCommandHandler_ExecuteCommand_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->ExecuteCommand(        
        std::move(p_command), std::move(callback));
      return true;
    }
  }
  return false;
}
