void BraveBrowserCommandHandlerAsyncWaiter::CanExecuteCommand(
    Command command_id, bool* out_can_execute) {
  base::RunLoop loop;
  proxy_->CanExecuteCommand(
      std::move(command_id),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_can_execute
,
             bool can_execute) {*out_can_execute = std::move(can_execute);
            loop->Quit();
          },
          &loop,
          out_can_execute));
  loop.Run();
}

bool BraveBrowserCommandHandlerAsyncWaiter::CanExecuteCommand(
    Command command_id) {
  bool async_wait_result;
  CanExecuteCommand(std::move(command_id),&async_wait_result);
  return async_wait_result;
}

void BraveBrowserCommandHandlerAsyncWaiter::ExecuteCommand(
    Command command, bool* out_executed) {
  base::RunLoop loop;
  proxy_->ExecuteCommand(
      std::move(command),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_executed
,
             bool executed) {*out_executed = std::move(executed);
            loop->Quit();
          },
          &loop,
          out_executed));
  loop.Run();
}

